 if(c.reference){c.reference=validateReference(c.reference);if(Math.round(c.height*.35)+c.reference.buildingHeight+2>c.height)throw Error('Aumente a altura Y para comportar as construções da referência.');}c.shell=shellConfig(c.shell);c.imageStrength=Number(c.imageStrength??.65);if(!Number.isFinite(c.imageStrength)||c.imageStrength<0||c.imageStrength>1)throw Error('Intensidade de imagem inválida.');return c;
