export function landscapeWindow(land,x,z,size=64){const c=land.config,{height}=windowShape(c,x,z,size),w=new World(size,height,size);for(let cz=z/16;cz<(z+size)/16;cz++)for(let cx=x/16;cx<(x+size)/16;cx++){const a=land.chunk(cx,cz),ids=a.palette.map(s=>w.id(s));for(let yy=0;yy<w.h;yy++)for(let zz=0;zz<16;zz++)for(let xx=0;xx<16;xx++)w.set(cx*16-x+xx,yy,cz*16-z+zz,ids[a.get(xx,yy,zz)]);}return w;}
